src/helios_lakehouse/common/config.py:
"""Catalog / volume / table path helpers.

Spark Declarative Pipelines inject configuration as spark.conf keys
prefixed with ``helios.``. Jobs pass the same values as CLI flags.
"""

from __future__ import annotations

import os
from dataclasses import dataclass


@dataclass(frozen=True)
class HeliosConfig:
    env: str
    catalog: str
    landing: str
    bronze_schema: str = "bronze"
    silver_schema: str = "silver"
    gold_schema: str = "gold"
    ml_schema: str = "ml"

    def fqn(self, schema: str, table: str) -> str:
        return f"{self.catalog}.{schema}.{table}"


def _conf(spark, key: str, default: str | None = None) -> str:
    if spark is not None:
        value = spark.conf.get(f"helios.{key}", None)
        if value:
            return value
    env_key = f"HELIOS_{key.upper()}"
    if os.environ.get(env_key):
        return os.environ[env_key]
    if default is not None:
        return default
    raise KeyError(f"Missing helios config: {key}")


def load_config(spark=None) -> HeliosConfig:
    return HeliosConfig(
        env=_conf(spark, "env", "dev"),
        catalog=_conf(spark, "catalog", "helios_dev"),
        landing=_conf(spark, "landing", "/Volumes/helios_dev/ops/landing"),
        bronze_schema=_conf(spark, "bronze_schema", "bronze"),
        silver_schema=_conf(spark, "silver_schema", "silver"),
        gold_schema=_conf(spark, "gold_schema", "gold"),
        ml_schema=_conf(spark, "ml_schema", "ml"),
    )


def landing_path(domain: str, spark=None) -> str:
    return f"{load_config(spark).landing.rstrip('/')}/{domain}"


def table_fqn(schema: str, table: str, spark=None) -> str:
    return load_config(spark).fqn(schema, table)


def bronze_table(name: str, spark=None) -> str:
    cfg = load_config(spark)
    return cfg.fqn(cfg.bronze_schema, name)

src/helios_lakehouse/common/transforms.p:
"""Pure transforms shared by pipelines and unit tests. No Spark import."""

from __future__ import annotations

from datetime import date
from typing import Optional

MAX_LINE_AMOUNT = 1_000_000.0


def normalize_sku(sku: Optional[str]) -> Optional[str]:
    if sku is None:
        return None
    cleaned = "".join(ch for ch in sku.strip().upper() if ch.isalnum() or ch in "-_")
    return cleaned or None


def is_plausible_amount(amount: Optional[float], *, max_abs: float = MAX_LINE_AMOUNT) -> bool:
    if amount is None:
        return False
    try:
        value = float(amount)
    except (TypeError, ValueError):
        return False
    return 0 <= value <= max_abs


def store_id_ok(store_id: Optional[str]) -> bool:
    if not store_id:
        return False
    s = store_id.strip()
    return len(s) == 4 and s.isdigit()


def week_id(d: date) -> str:
    iso = d.isocalendar()
    return f"{iso.year}-W{iso.week:02d}"


def recency_days(last_purchase: date, as_of: date) -> int:
    return max(0, (as_of - last_purchase).days)


def demand_label(units: float, in_stock: bool) -> tuple[float, bool]:
    """Return (observed_units, censored). Out-of-stock sales are a lower bound."""
    observed = max(0.0, float(units))
    return observed, (not in_stock)

src/helios_lakehouse/gold/sales_daily.py:
"""Store-SKU daily sales mart."""

from __future__ import annotations

from helios_lakehouse.common.config import load_config

try:
    from pyspark import pipelines as dp
except ImportError:
    import dlt as dp  # type: ignore

from pyspark.sql import functions as F


@dp.table(
    name="sales_daily",
    comment="Grain: business_date, store_id, sku, channel. Fed to BI and demand features.",
    table_properties={
        "quality": "gold",
        "delta.enableChangeDataFeed": "true",
        "delta.dataSkippingNumIndexedCols": "4",
    },
)
@dp.expect("positive_net_sales", "net_sales >= 0")
def sales_daily():
    cfg = load_config()
    tx = spark.read.table(f"{cfg.catalog}.{cfg.silver_schema}.transactions")  # noqa: F821
    return (
        tx.withColumn("business_date", F.to_date("event_ts"))
        .groupBy("business_date", "store_id", "sku", "channel")
        .agg(
            F.sum("qty").alias("units"),
            F.sum("amount").alias("net_sales"),
            F.countDistinct("transaction_id").alias("ticket_count"),
        )
    )

src/helios_lakehouse/silver/customers_sc:
"""Customer SCD2 dimension from CRM bronze."""

from __future__ import annotations

from helios_lakehouse.common.config import load_config

try:
    from pyspark import pipelines as dp
except ImportError:
    import dlt as dp  # type: ignore

from pyspark.sql import functions as F
from pyspark.sql.window import Window


@dp.table(
    name="customers_scd2",
    comment="SCD2 customer dimension. current_flag marks the live row.",
    table_properties={"quality": "silver", "delta.enableChangeDataFeed": "true"},
)
@dp.expect_or_drop("has_customer_id", "customer_id IS NOT NULL")
def customers_scd2():
    cfg = load_config()
    src = spark.read.table(f"{cfg.catalog}.{cfg.bronze_schema}.customer_profiles_raw")  # noqa: F821
    w = Window.partitionBy("customer_id").orderBy(F.col("_ingest_ts").asc())
    ranked = src.withColumn("_rn", F.row_number().over(w)).withColumn(
        "valid_from", F.col("_ingest_ts")
    )
    nxt = Window.partitionBy("customer_id").orderBy("valid_from")
    return (
        ranked.withColumn("valid_to", F.lead("valid_from").over(nxt))
        .withColumn("current_flag", F.col("valid_to").isNull())
        .drop("_rn")
    )
